2280	        // NaN/Inf 准入：不制造速度（复核反例）。
2281	        if (inertialVelocityPxPerMs != inertialVelocityPxPerMs || abs(inertialVelocityPxPerMs) > 1.0e300) {
2282	            inertialVelocityPxPerMs = 0.0
2283	            inertialSubPixelRemainder = 0.0
2284	            inertialElapsedNs = 0
2285	            return false
2286	        }
2287	        let elapsedNs = (now - inertialLastTick).toNanoseconds()
2288	        if (elapsedNs < 0) {
2289	            // 时钟倒退：终结活动（不制造位移）。
2290	            inertialVelocityPxPerMs = 0.0
2291	            inertialSubPixelRemainder = 0.0
2292	            inertialElapsedNs = 0
2293	            return false
2294	        }
2295	        if (elapsedNs == 0) {
