2297	        }
2298	        // 工作上界：总时长超过 inertialMaxDurationMs 即终结。
2299	        inertialElapsedNs += elapsedNs
2300	        if (inertialElapsedNs > CjguiComposableUiScrollViewport.inertialMaxDurationMs * 1_000_000) {
2301	            inertialVelocityPxPerMs = 0.0
2302	            inertialSubPixelRemainder = 0.0
2303	            inertialElapsedNs = 0
2304	            return false
2305	        }
2306	        let elapsedMs = Float64(elapsedNs) / 1_000_000.0
2307	        // 解析衰减 v(t) = v0 * exp(-t/τ)（帧率无关）。
