2333	        if (newVelocity < CjguiComposableUiScrollViewport.inertialStopVelocityPxPerMs &&
2334	            newVelocity > -CjguiComposableUiScrollViewport.inertialStopVelocityPxPerMs) {
2335	            inertialVelocityPxPerMs = 0.0
